mapper.select:
SELECT  FROM material_attachment WHERE owner_id=#{owner}
AND id > #{cursor}
AND file_name LIKE #{pattern} ESCAPE '!'
ORDER BY id LIMIT #{limit}

SELECT  FROM material_parse_run WHERE owner_id=#{owner} AND attachment_id=#{id}
AND (created_at < #{beforeTime} OR (created_at=#{beforeTime} AND id < #{beforeId}))
ORDER BY created_at DESC,id DESC LIMIT #{limit}

SELECT  FROM material_excerpt WHERE owner_id=#{owner} AND attachment_id=#{id}
AND EXISTS(SELECT 1 FROM material_excerpt_lifecycle l
  WHERE l.owner_id=material_excerpt.owner_id AND l.excerpt_id=material_excerpt.id
    AND l.attachment_id=material_excerpt.attachment_id
    AND l.status=#{status}
    AND l.ai_use=#{aiUse})
AND id>#{cursor}
AND (text LIKE #{pattern} ESCAPE '!' OR locator LIKE #{pattern} ESCAPE '!')
ORDER BY id LIMIT #{limit}
